public class Main {
    static void check(int n) throws Exception {
        if (n > 1) {
            throw new Exception("big" + n);
        }
    }
    public static void main(String[] args) throws Exception {
        int n = 0;
        try {
            while (true) {
                check(n++);
                System.out.print(n);
            }
        } catch (RuntimeException e) {
            System.out.print("R");
        } finally {
            System.out.print("F");
        }
        System.out.print("E");
    }
}

