class Basic implements Counter {
    protected int n = 10;
    public int next() { return ++n; }
}
class Twice extends Basic {
    private final int step;
    Twice(int step) { this.step = step; }
    public int next() {
        int n = this.n;
        for (var i = 0; i < step; i++) n += super.next();
        return n;
    }
}
