interface Shifter { int shift(int v); }
class Base {
    protected int val = 10;
    int calc(int val) {
        val += this.val;
        return val;
    }
}
class Derived extends Base implements Shifter {
    protected int val = 20;
    public int shift(int v) {
        final var tmp = v + super.val;
        return tmp + this.val;
    }
    @Override
    int calc(int val) {
        var r = super.calc(val);
        { int z = r + this.val; r = z; }
        return r;
    }
}
public class Main {
    public static void main(String[] args) {
        Base b = new Derived();
        Shifter s = new Derived();
        System.out.println(b.calc(1) + "," + b.val + "," + s.shift(2));
