class Base {
    protected int n = 1;
    int bump(int n) { n += 1; return n; }
}
class Step extends Base implements Counter {
    int n = 10;
    public int next() {
        final int k;
        if (super.n > 0) { k = n; } else { k = 0; }
        var list = new int[]{k, this.n, super.n};
        int n = list.length;
        return n + bump(n) + list[0];
    }
}
public class Main {
    public static void main(String[] args) {
        Counter c = new Step();
        int n = c.next();
        for (int i = 0; i < 2; i++) { n += i; }
