interface Tagger { String tag(String s); }
class Base implements Tagger {
    protected String s = "b";
    public String tag(String s) {
        s += "1";
        this.s += s;
        return this.s;
    }
}
class Sub extends Base {
    public String tag(String s) {
        String r = super.tag(s + 2);
        s = s + r;
        return s;
    }
}
public class Main {
    public static void main(String[] args) {
        Tagger t = new Sub();
        String x = "x";
        String y = t.tag(x);
        System.out.println(x + y + 1 + 2);
        StringBuilder sb = new StringBuilder("ab");
        StringBuilder sb2 = sb.append(1).append(2);
