class Slot {
    int[] cells = new int[3];
    void put(int i, int v) {
        try {
            cells[i] = v;
        } catch (ArrayIndexOutOfBoundsException e) {
            cells = new int[] {v, v};
        } finally {
            cells[0]++;
        }
    }
}
