class Shelf {
    protected int[] slots = new int[3];
    int put(int idx, int val) { slots[idx] = val; return idx + 1; }
}
class Rack extends Shelf {
    Rack() { slots = new int[2]; }
    @Override
    int put(int idx, int val) { return super.put(idx, val * 2); }
}
public class Main {
    public static void main(String[] args) {
        Shelf s = new Rack();
        int next = 0;
        try {
            for (int i = 0; i < 3; i++) {
                next = s.put(next, i + 1);
            }
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("AIOOBE " + next);
        } finally {
            System.out.println(java.util.Arrays.toString(s.slots));
        }
    }
}

