import java.util.*;
public class Main {
    interface Source { List<Integer> items(); }
    static class Fixed implements Source {
        public List<Integer> items() { return List.of(1, 2, 3); }
    }
    static class Mutable extends Fixed {
        @Override public List<Integer> items() { return new ArrayList<>(super.items()); }
    }
    public static void main(String[] args) {
        Source s1 = new Fixed();
        Source s2 = new Mutable();
        int done = 0;
        for (Source s : new Source[] {s1, s2}) {
            List<Integer> l = s.items();
            try {
                l.add(4);
                l.remove(0);
                l.set(5, 9);
                done++;
            } catch (UnsupportedOperationException e) {
                System.out.println("U" + l.size());
            } catch (IndexOutOfBoundsException e) {
                System.out.println("I" + l);
            } finally {
                done += 10;
            }
        }
        System.out.println(done);
    }
}

