import java.util.*;
interface Pick { boolean ok(String s); }
class Long3 implements Pick {
    public boolean ok(String s) { return s.length() > 3; }
}
public class Main {
    public static void main(String[] args) {
        List<String> src = new ArrayList<>(List.of("ant", "bear", "cat", "dove", "eel"));
        List<String> out = new ArrayList<>();
        Pick p = new Long3();
        for (int i = 0; i < src.size(); i++) {
            String s = src.get(i);
            if (p.ok(s)) {
                out.add(0, s);
                src.remove(i);
            } else if (s.startsWith("c")) {
                out.add(s);
            }
        }
        System.out.println(src + " " + out);
    }
}

