class Base implements Scaler {
    protected int k = 3;
    public int scale(int v) { return v * k; }
}
class Derived extends Base {
    protected int k = 5;
    public int scale(int v) { return v / k + super.k; }
}
public class Main {
    public static void main(String[] args) {
        Base ref = new Derived();
        short s = 4;
        char c = 'A';
        int total = 0;
        total += ref.scale(s + c);
        total += ref.k;
        double d = total / 4;
        try {
            long big = Integer.MAX_VALUE;
            int small = (int) (big + 1);
            System.out.println(total + " " + d + " " + (small < 0));
            System.out.println(10 / (total - total));
        } catch (ArithmeticException ex) {
            System.out.println("div");
        }
    }
}

