public class Main {
    interface Calc { int apply(int v); }
    static class Base implements Calc {
        protected int n = 5;
        public int apply(int v) { return v + n++; }
    }
    static class Derived extends Base {
        protected int n = 10;
        public int apply(int v) {
            byte b = (byte) (v * 2);
            b += super.n;
            return b + n--;
        }
    }
    public static void main(String[] args) {
        Calc c = new Derived();
        int r = 0;
        try {
            for (int i = 100; i < 103; i++) {
                r += c.apply(i);
            }
        } finally {
            System.out.println(r);
        }
    }
}

