public class Main {
    static int calls = 0;
    static boolean hit(boolean b) { calls++; return b; }
    static class Flag {
        int bits;
        Flag(int bits) { this.bits = bits; }
        boolean has(int m) { return (bits & m) == m; }
    }
    static class MaskFlag extends Flag {
        MaskFlag(int bits) { super(bits << 1); }
        @Override boolean has(int m) { return super.has(m >> 1); }
    }
    public static void main(String[] args) {
        Flag f = new MaskFlag(5);
        boolean x = hit(false) && hit(true);
        boolean y = hit(true) || hit(false);
        boolean z = hit(false) & hit(true);
        boolean w = hit(true) | hit(false);
        int k = f.has(4) ? (f.has(2) ? 1 : 2) : 3;
        System.out.println(calls + " " + x + y + z + w);
        System.out.println(k + " " + (f.bits ^ 3) + " " + (-8 >>> 28) + " " + (~f.bits));
    }
}

