interface Grader { String grade(int score); }
class Strict implements Grader {
    public String grade(int score) {
        return switch (score / 10) {
            case 10, 9 -> "A";
            case 8 -> "B";
            case 7 -> {
                if (score % 10 >= 5) yield "C+";
                yield "C";
            }
            default -> throw new IllegalStateException("fail:" + score);
        };
    }
}
class Lenient extends Strict {
    @Override
    public String grade(int score) {
        try {
            return super.grade(score + 5);
        } catch (IllegalStateException e) {
            return "D(" + e.getMessage() + ")";
        }
    }
}
