interface Task {
    int run(int limit);
}
class Looper implements Task {
    public int run(int limit) {
        int count = 0;
        int i = 0;
        outer:
        while (i < 5) {
            i++;
            int j = 0;
            do {
                j++;
                if (j == 2) continue;
                if (i == 2) continue outer;
                if (i + j > limit) break outer;
                count += i * j;
            } while (j < 3);
            count++;
        }
        return count * 10 + i;
    }
}
