interface Step { int apply(int v); }
class Doubler implements Step {
    public int apply(int v) { return v * 2; }
}
class Adder implements Step {
    private final int k;
    Adder(int k) { this.k = k; }
    public int apply(int v) { return v + k; }
}
public class Main {
    public static void main(String[] args) {
        Step[] steps = { new Doubler(), new Adder(3), new Doubler() };
        int total = 0;
        outer:
        for (int i = 0; i < 3; i++) {
            int v = i;
            for (Step s : steps) {
                v = s.apply(v);
                if (v > 10) continue outer;
                if (v == 5) break outer;
            }
            total += v;
            System.out.println("i=" + i + " v=" + v);
        }
        System.out.println("total=" + total);
    }
}

