class Stop extends Exception { Stop(String m) { super(m); } }
class Walker {
    int step(int i) throws Stop { if (i == 3) throw new Stop("s" + i); return i * 2; }
}
class Runner extends Walker {
    int step(int i) throws Stop { return i % 2 == 1 ? super.step(i) : i * 10; }
}
public class Main {
    public static void main(String[] args) {
        Walker w = new Runner();
        int sum = 0, i = 0;
        loop:
        while (true) {
            try {
                if (++i > 6) break loop;
                sum += w.step(i);
                if (sum > 100) continue;
            } catch (Stop e) {
                System.out.println(e.getMessage());
                continue loop;
            } finally {
                sum++;
            }
            System.out.println(i + ":" + sum);
        }
        System.out.println(sum);
    }
}

