interface Priced { int price(); }
record Item(String name, int price) implements Priced {
    Item {
        if (price < 0) throw new IllegalArgumentException("neg");
        name = name.trim();
    }
    Item(String name) { this(name, 100); }
    static int total = 0;
    static Item of(String n, int p) {
        total += p;
        return new Item(n, p);
    }
}
public class Main {
    public static void main(String[] args) {
        Priced a = Item.of(" pen ", 30);
        Item b = new Item(" ink");
        try {
            Item.of("bad", -5);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        } finally {
            System.out.println(Item.total);
        }
        System.out.println(a.price() + b.price() + b.name().length());
    }
}

